import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.DT_qyuxR.js";const h=JSON.parse('{"title":"Zones","description":"","frontmatter":{},"headers":[],"relativePath":"regles/08-zones.md","filePath":"regles/08-zones.md"}'),n={name:"regles/08-zones.md"};function r(l,e,i,d,u,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="zones" tabindex="-1">Zones <a class="header-anchor" href="#zones" aria-label="Permalink to &quot;Zones&quot;">​</a></h1><h2 id="les-trois-zones-du-bal" tabindex="-1">Les trois zones du bal <a class="header-anchor" href="#les-trois-zones-du-bal" aria-label="Permalink to &quot;Les trois zones du bal&quot;">​</a></h2><p>Le Carnaval est composé de <strong>3 zones</strong> (salons vocaux). Les joueurs se déplacent librement entre eux pendant la phase de Débats.</p><table tabindex="0"><thead><tr><th>Salon</th><th>Nom</th><th>Ambiance</th></tr></thead><tbody><tr><td>La Grande Tente</td><td>Le cœur du bal. Lumineux, bruyant, central.</td><td></td></tr><tr><td>La Foire aux Monstres</td><td>Les attractions sombres. Loin des regards.</td><td></td></tr><tr><td>Le Cimetière des Caravanes</td><td>Les tombes des anciens carnavals. Glacial, isolé.</td><td></td></tr></tbody></table><h2 id="deplacement" tabindex="-1">Déplacement <a class="header-anchor" href="#deplacement" aria-label="Permalink to &quot;Déplacement&quot;">​</a></h2><h3 id="quand-se-deplacer" tabindex="-1">Quand se déplacer ? <a class="header-anchor" href="#quand-se-deplacer" aria-label="Permalink to &quot;Quand se déplacer ?&quot;">​</a></h3><ul><li><strong>Pendant les Débats</strong> : les joueurs se déplacent <strong>librement</strong> entre les 3 zones.</li><li><strong>Pendant la Nuit</strong> : les déplacements sont <strong>verrouillés</strong>. Chaque joueur reste dans le salon où il se trouve.</li><li><strong>Pendant les Duels</strong> : les déplacements sont <strong>verrouillés</strong>.</li><li><strong>Pendant les Actions de Jour</strong> : les déplacements sont <strong>libres</strong> (mais les conditions vocales sont vérifiées à la soumission).</li></ul><h3 id="comment-se-deplacer" tabindex="-1">Comment se déplacer ? <a class="header-anchor" href="#comment-se-deplacer" aria-label="Permalink to &quot;Comment se déplacer ?&quot;">​</a></h3><p>Via le bot Discord, le joueur sélectionne le salon vocal dans lequel il souhaite se rendre. Le bot le déplace automatiquement.</p><h2 id="importance-des-zones" tabindex="-1">Importance des zones <a class="header-anchor" href="#importance-des-zones" aria-label="Permalink to &quot;Importance des zones&quot;">​</a></h2><p>Les zones ne sont pas juste cosmétiques — elles ont un <strong>impact mécanique</strong> :</p><h3 id="capacites-verifiant-la-position" tabindex="-1">Capacités vérifiant la position <a class="header-anchor" href="#capacites-verifiant-la-position" aria-label="Permalink to &quot;Capacités vérifiant la position&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Masque</th><th>Capacité</th><th>Condition</th></tr></thead><tbody><tr><td>Poursuite</td><td>Traque</td><td>La cible doit être dans un salon <strong>différent</strong> du vôtre</td></tr><tr><td>Sacrifice</td><td>Percée</td><td>La cible doit être dans le <strong>même</strong> salon que vous</td></tr></tbody></table><h3 id="strategie-de-deplacement" tabindex="-1">Stratégie de déplacement <a class="header-anchor" href="#strategie-de-deplacement" aria-label="Permalink to &quot;Stratégie de déplacement&quot;">​</a></h3><ul><li><strong>Pour le Poursuite</strong> : traquez les joueurs isolés dans d&#39;autres zones.</li><li><strong>Pour le Sacrifice</strong> : restez dans la même zone que votre cible.</li><li><strong>Pour les autres</strong> : déplacez-vous pour fuir les menaces ou pour vous rapprocher d&#39;alliés.</li></ul><h3 id="position-et-information" tabindex="-1">Position et information <a class="header-anchor" href="#position-et-information" aria-label="Permalink to &quot;Position et information&quot;">​</a></h3><p>La position des joueurs est <strong>visible par tous</strong> (qui est dans quel salon). C&#39;est une information publique qui peut être exploitée.</p><ul><li>&quot;Pourquoi X est-il toujours dans le Cimetière ?&quot;</li><li>&quot;Y et Z sont dans la même zone — sont-ils alliés ?&quot;</li><li>&quot;Le joueur isolé dans la Foire aux Monstres est une cible facile pour le Poursuite.&quot;</li></ul><h2 id="verrouillage-vocal" tabindex="-1">Verrouillage vocal <a class="header-anchor" href="#verrouillage-vocal" aria-label="Permalink to &quot;Verrouillage vocal&quot;">​</a></h2><h3 id="quand-les-salons-sont-verrouilles" tabindex="-1">Quand les salons sont verrouillés ? <a class="header-anchor" href="#quand-les-salons-sont-verrouilles" aria-label="Permalink to &quot;Quand les salons sont verrouillés ?&quot;">​</a></h3><p>Les salons vocaux sont verrouillés par le bot pendant :</p><ul><li>La <strong>Nuit</strong> (actions secrètes)</li><li>Les <strong>Duels</strong> (affrontements)</li><li>La <strong>Résolution</strong> (résolution des actions de Nuit)</li></ul><h3 id="comment" tabindex="-1">Comment ? <a class="header-anchor" href="#comment" aria-label="Permalink to &quot;Comment ?&quot;">​</a></h3><p>Le bot modifie les permissions des salons vocaux pour empêcher les déplacements et les messages.</p><h3 id="deverrouillage" tabindex="-1">Déverrouillage <a class="header-anchor" href="#deverrouillage" aria-label="Permalink to &quot;Déverrouillage&quot;">​</a></h3><p>Les salons sont déverrouillés automatiquement quand la phase suivante commence (Débats ou Actions de Jour).</p>',26)])])}const p=t(n,[["render",r]]);export{h as __pageData,p as default};
